# Verify the HTML report is valid and self-contained
from html.parser import HTMLParser

class HTMLValidator(HTMLParser):
    def __init__(self):
        super().__init__()
        self.tags = []
        self.errors = []
        self.img_count = 0
        self.has_html = False
        self.has_body = False
        self.has_head = False

    def handle_starttag(self, tag, attrs):
        self.tags.append(tag)
        if tag == 'img':
            self.img_count += 1
            src = dict(attrs).get('src', '')
            if not src.startswith('data:image/png;base64,'):
                self.errors.append(f'Image without base64 src: {src[:50]}')
        if tag == 'html':
            self.has_html = True
        if tag == 'body':
            self.has_body = True
        if tag == 'head':
            self.has_head = True

    def handle_endtag(self, tag):
        if self.tags and self.tags[-1] == tag:
            self.tags.pop()

    def validate(self):
        issues = []
        if not self.has_html:
            issues.append('Missing <html> tag')
        if not self.has_head:
            issues.append('Missing <head> tag')
        if not self.has_body:
            issues.append('Missing <body> tag')
        if self.tags:
            issues.append(f'Unclosed tags: {self.tags}')
        return issues

